void BeginCollect(const int32 InNumTriangles)
{
	const int32 ExpectedNumContacts = FMath::Min(InNumTriangles * 4, Settings.MaxContactsBufferSize);
	Reset(InNumTriangles, ExpectedNumContacts);
}

// Add a triangle that we might be overlapping
void AddTriangle(const FTriangle& MeshTriangle, const int32 MeshTriangleIndex, const int32 VertexIndex0, const int32 VertexIndex1, const int32 VertexIndex2)
{
	Triangles.Emplace(MeshTriangle, MeshTriangleIndex, VertexIndex0, VertexIndex1, VertexIndex2);
}

// Process all the added triangles to generate connectivity metadata etc
void EndCollect()
{
	for (int32 LocalTriangleIndex = 0; LocalTriangleIndex < GetNumTriangles(); ++LocalTriangleIndex)
	{
		const FTriangleExt& Triangle = Triangles[LocalTriangleIndex];
		AddTriangleEdge(LocalTriangleIndex, Triangle.GetVertexIndex(0), Triangle.GetVertexIndex(1));
		AddTriangleEdge(LocalTriangleIndex, Triangle.GetVertexIndex(1), Triangle.GetVertexIndex(2));
		AddTriangleEdge(LocalTriangleIndex, Triangle.GetVertexIndex(2), Triangle.GetVertexIndex(0));
	}
}

void AddTriangleEdge(const int32 LocalTriangleIndex, const int32 VertexIndex0, const int32 VertexIndex1)
{
	const FContactEdgeID EdgeID = FContactEdgeID(VertexIndex0, VertexIndex1);
	FEdgeTriangleIndices* EdgeTriangleIndices = EdgeTriangleIndicesMap.Find(EdgeID);
	if (EdgeTriangleIndices == nullptr)
	{
		EdgeTriangleIndicesMap.Emplace(EdgeID, EdgeID, LocalTriangleIndex, INDEX_NONE);
	}
	else
	{
		EdgeTriangleIndices->LocalTriangleIndices[1] = LocalTriangleIndex;
	}
}

bool IsSharedEdge(const FContactEdgeID& EdgeID) const
{
	const FEdgeTriangleIndices* EdgeTriangleIndices = EdgeTriangleIndicesMap.Find(EdgeID);
	if (EdgeTriangleIndices != nullptr)
	{
		return (EdgeTriangleIndices->LocalTriangleIndices[0] != INDEX_NONE) && (EdgeTriangleIndices->LocalTriangleIndices[1] != INDEX_NONE);
	}
	return false;
}

int32 GetOtherTriangleIndexForEdge(const int32 LocalTriangleIndex, const FContactEdgeID& EdgeID)
{
	FEdgeTriangleIndices* EdgeTriangleIndices = EdgeTriangleIndicesMap.Find(EdgeID);
	if (EdgeTriangleIndices != nullptr)
	{
		return (EdgeTriangleIndices->LocalTriangleIndices[0] == LocalTriangleIndex) ? EdgeTriangleIndices->LocalTriangleIndices[1] : EdgeTriangleIndices->LocalTriangleIndices[0];
	}
	return INDEX_NONE;
}

inline bool GetTriangleEdgeVerticesAtPosition(
	const FVec3& Position, 
	const FVec3 VertexA, const FVec3 VertexB, const FVec3 VertexC,
	int32& OutEdgeVertexIndexA, int32& OutEdgeVertexIndexB, 
	const FReal BaryCentricTolerance = UE_KINDA_SMALL_NUMBER)
{
	OutEdgeVertexIndexA = INDEX_NONE;
	OutEdgeVertexIndexB = INDEX_NONE;

	const FVec3 BaryCentric = ToBarycentric(Position, VertexA, VertexB, VertexC);

	// Is it a vertex contact?
	if (FMath::IsNearlyEqual(BaryCentric.X, FReal(1), BaryCentricTolerance))
	{
		OutEdgeVertexIndexA = 0;
		return true;
	}
	if (FMath::IsNearlyEqual(BaryCentric.Y, FReal(1), BaryCentricTolerance))
	{
		OutEdgeVertexIndexA = 1;
		return true;
	}
	if (FMath::IsNearlyEqual(BaryCentric.Z, FReal(1), BaryCentricTolerance))
	{
		OutEdgeVertexIndexA = 2;
		return true;
	}

	// Is it an edge contact?
	if (FMath::IsNearlyEqual(BaryCentric.X, FReal(0), BaryCentricTolerance))
	{
		OutEdgeVertexIndexA = 1;
		OutEdgeVertexIndexB = 2;
		return true;
	}
	if (FMath::IsNearlyEqual(BaryCentric.Y, FReal(0), BaryCentricTolerance))
	{
		OutEdgeVertexIndexA = 2;
		OutEdgeVertexIndexB = 0;
		return true;
	}
	if (FMath::IsNearlyEqual(BaryCentric.Z, FReal(0), BaryCentricTolerance))
	{
		OutEdgeVertexIndexA = 0;
		OutEdgeVertexIndexB = 1;
		return true;
	}

	return false;
}

// ID for a vertex in a trangle mesh, used by FTriangleContactPointData
using FContactVertexID = int32;

// ID for an edge in a trangle mesh, used by FTriangleContactPointData
struct FContactEdgeID
{
	FORCEINLINE FContactEdgeID()
		: VertexIDs{ INDEX_NONE, INDEX_NONE }
	{
	}

	FORCEINLINE FContactEdgeID(const FContactVertexID VertexIndexA, const FContactVertexID VertexIndexB)
	{
		// EdgeID is the same if we swap the vertex indices
		// The check for INDEX_NONE allows us to use an EdgeID as a VertexID without swapping order
		if ((VertexIndexA < VertexIndexB) || (VertexIndexB == INDEX_NONE))
		{
			VertexIDs[0] = VertexIndexA;
			VertexIDs[1] = VertexIndexB;
		}
		else
		{
			VertexIDs[0] = VertexIndexB;
			VertexIDs[1] = VertexIndexA;
		}
	}

	FORCEINLINE bool IsValid() const
	{
		return (VertexIDs[0] != INDEX_NONE) && (VertexIDs[1] != INDEX_NONE);

inline TVec3<RealType> ToBarycentric(const TVec3<RealType>& Point, const TVec3<RealType>& V0, const TVec3<RealType>& V1, const TVec3<RealType>& V2)
{
	const TVec3<RealType> V02 = V0 - V2;
	const TVec3<RealType> V12 = V1 - V2;
	const TVec3<RealType> PV2 = Point - V2;
	const RealType M00 = V02.Dot(V02);
	const RealType M01 = V02.Dot(V12);
	const RealType M11 = V12.Dot(V12);
	const RealType R0 = V02.Dot(PV2);
	const RealType R1 = V12.Dot(PV2);
	const RealType Det = M00 * M11 - M01 * M01;
	RealType Bary1, Bary2, Bary3;
	if (Det > UE_SMALL_NUMBER)
	{
		// Non-degenerate triangle
		const RealType InvDet = RealType(1) / Det;
		Bary1 = (M11 * R0 - M01 * R1) * InvDet;
		Bary2 = (M00 * R1 - M01 * R0) * InvDet;
		Bary3 = RealType(1) - Bary1 - Bary2;
	}
	else
	{
		const bool bHaveLine02 = (M00 > UE_SMALL_NUMBER);
		const bool bHaveLine12 = (M11 > UE_SMALL_NUMBER);
		const bool bInsideLine02 = ((M00 > UE_SMALL_NUMBER) && (R0 >= 0) && (R0 <= M00));
		const bool bInsideLine12 = ((M11 > UE_SMALL_NUMBER) && (R1 >= 0) && (R1 <= M11));
		if (bInsideLine02 || (bHaveLine02 && !bInsideLine12))
		{
			// Line-degenerate and point on line segment V02
			const RealType Alpha02 = R0 / M00;
			Bary1 = Alpha02;
			Bary2 = RealType(0);
			Bary3 = RealType(1) - Alpha02;
		}
		else if (bHaveLine12)
		{
			// Line-degenerate and point on line segment V12
			const RealType Alpha12 = R1 / M11;
			Bary1 = RealType(0);
			Bary2 = Alpha12;
			Bary3 = RealType(1) - Alpha12;
		}
		else
		{
			// Point-degenerate, or line-degenerate and point not on line
			Bary1 = RealType(1);
			Bary2 = RealType(0);
			Bary3 = RealType(0);
		}
	}
	return TVec3<RealType>(Bary1, Bary2, Bary3);
}

// Enable Motion-Aware Collision Detection if either particle requests it
// (NOTE: MACD also affects how the particle world-space bounds is expanded in the broadphase)
const bool bIsMACD = Context.GetSettings().bAllowMACD && (CVars::bChaosForceMACD || P0->MACDEnabled() || P1->MACDEnabled());
Flags.bIsMACD = bIsMACD;

FVec3f RelativeMovement = FVec3f(0);
if (!Flags.bIsMACD)
{
	// We increase CullDistance based on velocity (up to a limit for perf with large velocities).
	// NOTE: This somewhat matches the bounds expansion in FPBDRigidsEvolutionGBF::Integrate
	// NOTE: We use PreV here which is the velocity after collisions from the previous tick because we want the 
	// velocity without gravity from this tick applied. This is mainly so that we get the same CullDistance from 
	// one tick to the next, even if one of the particles goes to sleep, and therefore its velocity is now zero 
	// because gravity is no longer applied. Also see FPBDIslandManager::PropagateIslandSleep for other issues 
	// related to velocity and sleeping...
	// NOTE: we used to extend the cull distance for CCD objects, but this is no longer required. The sweep and
	// rewind phase does not use CullDistance, and once rewound we are using normal collision detection where
	// an expanded CullDistance doesn't help and makes perf worse.
	const FRealSingle VMax0 = P0->GetPreVf().GetAbsMax();
	const FRealSingle VMax1 = P1->GetPreVf().GetAbsMax();
	const FRealSingle VMaxDt = FMath::Max(VMax0, VMax1) * Dt;
	const FRealSingle VelocityBoundsMultiplier = FRealSingle(Context.GetSettings().BoundsVelocityInflation);
	const FRealSingle MaxVelocityBoundsExpansion = FRealSingle(Context.GetSettings().MaxVelocityBoundsExpansion);
	if ((VelocityBoundsMultiplier > 0) && (MaxVelocityBoundsExpansion > 0))
	{
		CullDistance += FMath::Min(VelocityBoundsMultiplier * VMaxDt, MaxVelocityBoundsExpansion);
	}
}
else
{
	// Movement-aware collision detection (MACD) takes the relative position change this tick as input
	// We do not expand CullDistance. Depending on the shape pair types involved, the collision detection
	// step will either pad the CullDistance itself, or ideally compare RelativeMovement with the contact 
	// normal when determining what contacts to cull. Eventually all shape pairs should do the latter.
	RelativeMovement = (P0->GetVf() - P1->GetVf()) * Dt;
}

// Run collision detection on all potentially colliding shape pairs
NumActiveConstraints = GenerateCollisionsImpl(Dt, CullDistance, RelativeMovement, Context);

	Private::FMeshContactGenerator& ContactGenerator)
{
	if (RelativeMovement.IsZero())
	{
		ConstructConvexMeshOneShotManifold2(Convex, ConvexTransform, Mesh, MeshTransform, MeshScale, InCullDistance, ContactGenerator);
	}
	else
	{
		FRigidTransform3 MeshToConvexTransform = MeshTransform.GetRelativeTransformNoScale(ConvexTransform);
		MeshToConvexTransform.SetScale3D(MeshScale);

		// NOTE: Convex bounds is extended backwards to encompass the pre-movement position
		const FVec3 ConvexRelativeMovement = ConvexTransform.InverseTransformVectorNoScale(RelativeMovement);
		const FAABB3 ConvexBounds = FAABB3(Convex.BoundingBox()).GrowByVector(-ConvexRelativeMovement).Thicken(InCullDistance);
		const FAABB3 MeshQueryBounds = ConvexBounds.InverseTransformedAABB(MeshToConvexTransform);
